package handler;

import app.Database;
import app.JsonUtil;
import app.SessionManager;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;
import java.io.*;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.sql.*;
import java.util.*;
import java.math.BigDecimal;

public class ShoppingListHandler implements HttpHandler {
  public void handle(HttpExchange ex) throws IOException {
    Integer userId=SessionManager.getUserId(ex.getRequestHeaders().getFirst("X-Session-Token"));
    if(userId==null){JsonResponse.send(ex,401,JsonResponse.error("Please log in first."));return;}
    String method=ex.getRequestMethod(), path=ex.getRequestURI().getPath();
    Map<String,String> data=new HashMap<>();
    if("POST".equalsIgnoreCase(method)) data=readForm(ex);
    try {
      if("GET".equalsIgnoreCase(method) && path.equals("/api/lists")) { sendLists(ex,userId); return; }
      if("GET".equalsIgnoreCase(method) && path.matches("/api/lists/\\d+")) { sendList(ex,userId,Integer.parseInt(path.substring(path.lastIndexOf('/')+1))); return; }
      if("POST".equalsIgnoreCase(method) && path.equals("/api/lists/create")) { create(ex,userId,data); return; }
      if("POST".equalsIgnoreCase(method) && path.equals("/api/lists/delete")) { deleteList(ex,userId,integer(data,"shoppingListId")); return; }
      if("POST".equalsIgnoreCase(method) && path.equals("/api/lists/items/add")) { add(ex,userId,integer(data,"shoppingListId"),integer(data,"productId"),integer(data,"quantity")); return; }
      if("POST".equalsIgnoreCase(method) && path.equals("/api/lists/items/update")) { update(ex,userId,integer(data,"shoppingListItemId"),integer(data,"quantity")); return; }
      if("POST".equalsIgnoreCase(method) && path.equals("/api/lists/items/remove")) { remove(ex,userId,integer(data,"shoppingListItemId")); return; }
      JsonResponse.send(ex,405,JsonResponse.error("Unsupported shopping-list endpoint."));
    } catch(IllegalArgumentException e){JsonResponse.send(ex,400,JsonResponse.error("Invalid or missing input."));}
      catch(SQLException e){JsonResponse.send(ex,500,JsonResponse.error("Shopping-list operation failed. Verify the database schema and connection."));}
  }
  private Map<String,String> readForm(HttpExchange ex)throws IOException{Map<String,String> m=new HashMap<>();String body=new String(ex.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);for(String pair:body.split("&")){if(pair.isEmpty())continue;String[] a=pair.split("=",2);m.put(URLDecoder.decode(a[0],"UTF-8"),a.length>1?URLDecoder.decode(a[1],"UTF-8"):"");}return m;}
  private int integer(Map<String,String> m,String k){String v=m.get(k);if(v==null)throw new NumberFormatException();return Integer.parseInt(v);}
  private boolean owns(Connection c,int list,int user)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM ShoppingLists WHERE ShoppingListID=? AND UserID=?")){p.setInt(1,list);p.setInt(2,user);try(ResultSet r=p.executeQuery()){return r.next();}}}
  private void create(HttpExchange ex,int user,Map<String,String>d)throws SQLException,IOException{String name=d.get("listName");if(name==null||name.trim().isEmpty()){JsonResponse.send(ex,400,JsonResponse.error("List name is required."));return;}try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO ShoppingLists(UserID,ListName) VALUES(?,?)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,user);p.setString(2,name.trim());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();JsonResponse.send(ex,201,"{\"shoppingListId\":"+r.getInt(1)+",\"listName\":"+JsonUtil.quote(name.trim())+"}");}}}
  private void sendLists(HttpExchange ex,int user)throws SQLException,IOException{String sql="SELECT sl.ShoppingListID,sl.ListName,sl.CreatedAt,COUNT(sli.ShoppingListItemID) itemCount,COALESCE(SUM(sli.Quantity * COALESCE((SELECT MIN(sp.Price-sp.Discount+sp.DeliveryCharge+sp.PlatformFee) FROM SellerProducts sp WHERE sp.ProductID=sli.ProductID AND sp.StockStatus<>'out_of_stock'),0)),0) estimatedTotal FROM ShoppingLists sl LEFT JOIN ShoppingListItems sli ON sli.ShoppingListID=sl.ShoppingListID WHERE sl.UserID=? GROUP BY sl.ShoppingListID,sl.ListName,sl.CreatedAt ORDER BY sl.ShoppingListID DESC";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,user);try(ResultSet r=p.executeQuery()){StringBuilder b=new StringBuilder("[");while(r.next()){if(b.length()>1)b.append(',');b.append("{\"shoppingListId\":").append(r.getInt("ShoppingListID")).append(",\"listName\":").append(JsonUtil.quote(r.getString("ListName"))).append(",\"createdAt\":").append(JsonUtil.quote(r.getTimestamp("CreatedAt").toString())).append(",\"itemCount\":").append(r.getInt("itemCount")).append(",\"estimatedTotal\":").append(r.getBigDecimal("estimatedTotal")).append('}');}b.append(']');JsonResponse.send(ex,200,b.toString());}}}
  private void sendList(HttpExchange ex,int user,int id)throws SQLException,IOException{try(Connection c=Database.getConnection()){if(!owns(c,id,user)){JsonResponse.send(ex,404,JsonResponse.error("Shopping list not found."));return;}String name;try(PreparedStatement p=c.prepareStatement("SELECT ListName FROM ShoppingLists WHERE ShoppingListID=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){r.next();name=r.getString(1);}}String sql="SELECT sli.ShoppingListItemID,p.ProductID,p.Name,p.Brand,sli.Quantity,COALESCE((SELECT MIN(sp.Price-sp.Discount+sp.DeliveryCharge+sp.PlatformFee) FROM SellerProducts sp WHERE sp.ProductID=p.ProductID AND sp.StockStatus<>'out_of_stock'),0) lowest FROM ShoppingListItems sli JOIN Products p ON p.ProductID=sli.ProductID WHERE sli.ShoppingListID=? ORDER BY sli.ShoppingListItemID";StringBuilder items=new StringBuilder("[");BigDecimal total=BigDecimal.ZERO;try(PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next()){if(items.length()>1)items.append(',');BigDecimal lowest=r.getBigDecimal("lowest"),line=lowest.multiply(BigDecimal.valueOf(r.getInt("Quantity")));total=total.add(line);items.append("{\"shoppingListItemId\":").append(r.getInt("ShoppingListItemID")).append(",\"productId\":").append(r.getInt("ProductID")).append(",\"productName\":").append(JsonUtil.quote(r.getString("Name"))).append(",\"brand\":").append(JsonUtil.quote(r.getString("Brand"))).append(",\"quantity\":").append(r.getInt("Quantity")).append(",\"lowestFinalCost\":").append(lowest).append(",\"lineEstimate\":").append(line).append('}');}}}items.append(']');JsonResponse.send(ex,200,"{\"shoppingListId\":"+id+",\"listName\":"+JsonUtil.quote(name)+",\"estimatedTotal\":"+total+",\"items\":"+items+"}");}}
  private void add(HttpExchange ex,int user,int list,int product,int qty)throws SQLException,IOException{if(qty<1||qty>99){JsonResponse.send(ex,400,JsonResponse.error("Quantity must be 1–99."));return;}try(Connection c=Database.getConnection()){if(!owns(c,list,user)){JsonResponse.send(ex,403,JsonResponse.error("List access denied."));return;}try(PreparedStatement p=c.prepareStatement("INSERT INTO ShoppingListItems(ShoppingListID,ProductID,Quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE Quantity=Quantity+VALUES(Quantity)")){p.setInt(1,list);p.setInt(2,product);p.setInt(3,qty);p.executeUpdate();}JsonResponse.send(ex,200,"{\"message\":\"Item added.\"}");}}
  private void update(HttpExchange ex,int user,int item,int qty)throws SQLException,IOException{if(qty<1||qty>99){JsonResponse.send(ex,400,JsonResponse.error("Quantity must be 1–99."));return;}try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE ShoppingListItems sli JOIN ShoppingLists sl ON sl.ShoppingListID=sli.ShoppingListID SET sli.Quantity=? WHERE sli.ShoppingListItemID=? AND sl.UserID=?")){p.setInt(1,qty);p.setInt(2,item);p.setInt(3,user);int n=p.executeUpdate();JsonResponse.send(ex,n>0?200:404,n>0?"{\"message\":\"Quantity updated.\"}":JsonResponse.error("Item not found."));}}
  private void remove(HttpExchange ex,int user,int item)throws SQLException,IOException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("DELETE sli FROM ShoppingListItems sli JOIN ShoppingLists sl ON sl.ShoppingListID=sli.ShoppingListID WHERE sli.ShoppingListItemID=? AND sl.UserID=?")){p.setInt(1,item);p.setInt(2,user);int n=p.executeUpdate();JsonResponse.send(ex,n>0?200:404,n>0?"{\"message\":\"Item removed.\"}":JsonResponse.error("Item not found."));}}
  private void deleteList(HttpExchange ex,int user,int id)throws SQLException,IOException{try(Connection c=Database.getConnection()){if(!owns(c,id,user)){JsonResponse.send(ex,404,JsonResponse.error("Shopping list not found."));return;}try(PreparedStatement p=c.prepareStatement("DELETE FROM ShoppingListItems WHERE ShoppingListID=?")){p.setInt(1,id);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("DELETE FROM ShoppingLists WHERE ShoppingListID=? AND UserID=?")){p.setInt(1,id);p.setInt(2,user);p.executeUpdate();}JsonResponse.send(ex,200,"{\"message\":\"List deleted.\"}");}}
}
